parameters.jsCode:
// 从你的数据里取图片URL数组
const urls =
  items[0].json.output?.["图片URL"] ??
  items[0].json["图片URL"] ??
  [];

// 过滤 http(s) + 去重
const seen = new Set();
const list = [];
for (const u of urls) {
  const s = String(u || '').trim();
  if (/^https?:\/\//i.test(s) && !seen.has(s)) {
    seen.add(s);
    list.push(s);
  }
}

// 生成 Markdown，多行
const image_markdown = list.map((u, i) => `[图片 ${i + 1}](${u})`).join('\n');

// 仅返回 1 个 item
return [{ json: { image_markdown } }];

